// Verus program: remove the first element of a non-empty Vec<i32>
// and return the remaining elements in the same order.
//
// Key spec points proved:
// - requires input length > 0
// - output length is exactly input length - 1
// - for every valid i in output: out[i] == a[i + 1]
// - input is not modified (a is borrowed immutably)

use vstd::prelude::*;

verus! {

fn remove_front(a: &Vec<i32>) -> (out: Vec<i32>)
    requires
        a.len() > 0,
    ensures
        out.len() == a.len() - 1,
        forall|i: int| 0 <= i && i < out.len() ==> out[i] == a[i + 1],
{
    let mut out: Vec<i32> = Vec::new();
    let mut i: usize = 1;

    while i < a.len()
        invariant
            1 <= i && i <= a.len(),
            out.len() == i - 1,
            forall|j: int| 0 <= j && j < out.len() ==> out[j] == a[j + 1],
    {
        out.push(a[i]);
        i += 1;
    }

    out
}

} // verus!